import React, { useState } from 'react';
import { Plus } from 'lucide-react';
import JobStats from '../components/JobStats';
import JobForm from '../components/JobForm';
import JobTable from '../components/JobTable';

function JobAdminPage() {
  const [jobs, setJobs] = useState([]);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingJob, setEditingJob] = useState(null);

  const addOrUpdateJob = (job) => {
    if (editingJob) {
      setJobs(jobs.map(j => j.id === editingJob.id ? { ...job, id: editingJob.id, createdAt: j.createdAt } : j));
      setEditingJob(null);
    } else {
      setJobs([...jobs, { ...job, id: Date.now(), createdAt: new Date().toLocaleDateString() }]);
    }
    setIsFormOpen(false);
  };

  const handleEdit = (job) => {
    setEditingJob(job);
    setIsFormOpen(true);
  };

  const handleDelete = (id) => {
    if (confirm('Are you sure you want to delete this job posting?')) {
      setJobs(jobs.filter(job => job.id !== id));
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="bg-white rounded-lg shadow p-6 mb-6 flex justify-between items-center">
          <h1 className="text-3xl font-bold text-gray-900">Job Administration</h1>
          <button
            onClick={() => setIsFormOpen(true)}
            className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700"
          >
            <Plus className="w-5 h-5" /> Add New Job
          </button>
        </div>

        {/* Stats */}
        <JobStats jobs={jobs} />

        {/* Jobs Table */}
        <JobTable jobs={jobs} onEdit={handleEdit} onDelete={handleDelete} />

        {/* Job Form Modal */}
        {isFormOpen && (
          <JobForm
            job={editingJob}
            onClose={() => setIsFormOpen(false)}
            onSubmit={addOrUpdateJob}
          />
        )}
      </div>
    </div>
  );
}

export default JobAdminPage;
